const express = require('express');
const app = express();
const fs = require('fs');

const port = 1327;

function input(i) {
    return `input_${i}.in`;
}

function output(i) {
    return `out_${i}.out`;
}


function writeScript(num) {
    const script =
`#!/bin/bash
# Generated by Competitive Companion (server/index.js). Java only.
echo "=============================="
echo "        Test Cases"
echo "=============================="
TEST_CASES=${num}
for (( i=0; i<TEST_CASES; i++ )); do
    java gtest < "input_\${i}.in" > "answer_\${i}.ans"
    if diff -w "answer_\${i}.ans" "out_\${i}.out" > /dev/null; then
        printf "\\e[32m✔ Passed %d\\e[0m\\n" "$((i+1))"
    else
        echo "Differences found in test case $((i+1)):"
        diff -w -u "answer_\${i}.ans" "out_\${i}.out"
        printf "\\e[31m✘ Failed %d\\e[0m\\n" "$((i+1))"
        exit 1
    fi
done
printf "\\e[32m\\nCongratulations, ACCEPTED\\e[0m\\n"
`;
    fs.writeFileSync("script.sh", script);
}

app.use(express.json());

app.post('/', (req, res) => {
    const data = req.body;
    const tests = data.tests;
    console.log(`Writing the following Test Cases ${JSON.stringify(tests)}`);
    const len = tests.length;
    for(let i = 0; i < len; ++i) {
        const inp = input(i);
        const out = output(i);
        fs.writeFileSync(inp, tests[i].input, err => {
            console.error(`Error in Writing file ${inp}: ${err}`);
        });
        fs.writeFileSync(out, tests[i].output, err => {
            console.error(`Error in Writing file ${out}: ${err}`);
        });
    }
    res.sendStatus(200);
    writeScript(len);
    process.exit(0);
})

app.listen(port, (err) => {
    if (err) {
        console.error(`Error Occured ${error}`);
        process.exit(1);
    }
    console.log(`Listening to Port ${port}`);
});
